import { useState } from "react";

/* COLORS */
const C = {
  black: "#0a0a0a",
  white: "#ffffff",
  gold: "#c9a84c",
  gray200: "#e0dbd2",
  gray400: "#9b9690",
  red: "#c0392b",
};

/* INPUT STYLE */
const inputStyle = (focus) => ({
  width: "100%",
  height: "48px",
  padding: "0 14px",
  border: `1.5px solid ${focus ? C.gold : C.gray200}`,
  borderRadius: "8px",
  outline: "none",
});

/* MAIN COMPONENT */
export default function Login() {
  const [identifier, setIdentifier] = useState("");
  const [password, setPassword] = useState("");
  const [showPw, setShowPw] = useState(false);
  const [error, setError] = useState("");
  const [success, setSuccess] = useState("");
  const [loading, setLoading] = useState(false);

  const [focusId, setFocusId] = useState(false);
  const [focusPw, setFocusPw] = useState(false);

  const handleLogin = () => {
    setError("");
    setSuccess("");

    if (!identifier.trim()) {
      setError("Email or Phone is required");
      return;
    }

    if (!password.trim()) {
      setError("Password is required");
      return;
    }

    setLoading(true);

    setTimeout(() => {
      setLoading(false);

      // ✅ OTP REMOVED
      setSuccess("🎉 Your account is created successfully!");
    }, 1000);
  };

  return (
    <div className="main-container">

      {/* LEFT PANEL */}
      <div className="login-left">
        <h2 className="logo">
          The<span>Zuro</span>
        </h2>
        <p className="tagline">
          Join India's fastest growing shopping platform 🚀
        </p>
      </div>

      {/* RIGHT PANEL */}
      <div className="login-right">
        <div className="form-container">

          <h2>Welcome Back 👋</h2>

          {/* ERROR */}
          {error && <div className="error">{error}</div>}

          {/* SUCCESS */}
          {success && <div className="success">{success}</div>}

          {/* INPUTS */}
          <input
            style={inputStyle(focusId)}
            placeholder="Email or Phone"
            value={identifier}
            onChange={(e) => setIdentifier(e.target.value)}
            onFocus={() => setFocusId(true)}
            onBlur={() => setFocusId(false)}
          />

          <div className="password-box">
            <input
              style={inputStyle(focusPw)}
              type={showPw ? "text" : "password"}
              placeholder="Password"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              onFocus={() => setFocusPw(true)}
              onBlur={() => setFocusPw(false)}
            />
            <span onClick={() => setShowPw(!showPw)}>👁</span>
          </div>

          {/* BUTTON */}
          <button onClick={handleLogin}>
            {loading ? "Loading..." : "Login"}
          </button>

        </div>
      </div>

      {/* CSS */}
      <style>{`

        * {
          box-sizing: border-box;
          margin: 0;
          padding: 0;
          font-family: Arial;
        }

        .main-container {
          display: flex;
          min-height: 100vh;
        }

        /* LEFT PANEL */
        .login-left {
          flex: 1;
          background: black;
          color: white;
          padding: 40px;
          display: flex;
          flex-direction: column;
          justify-content: center;
        }

        .logo span {
          color: ${C.gold};
        }

        .tagline {
          margin-top: 10px;
          color: #ccc;
        }

        /* RIGHT PANEL */
        .login-right {
          width: 100%;
          max-width: 500px;
          display: flex;
          align-items: center;
          justify-content: center;
          padding: 40px;
        }

        .form-container {
          width: 100%;
          max-width: 380px;
        }

        h2 {
          margin-bottom: 20px;
        }

        input {
          margin-bottom: 15px;
        }

        .password-box {
          position: relative;
        }

        .password-box span {
          position: absolute;
          right: 10px;
          top: 12px;
          cursor: pointer;
        }

        button {
          width: 100%;
          height: 45px;
          background: black;
          color: white;
          border: none;
          border-radius: 6px;
          cursor: pointer;
        }

        .error {
          color: red;
          margin-bottom: 10px;
        }

        .success {
          color: green;
          margin-bottom: 10px;
          font-weight: bold;
        }

        /* 🔥 MOBILE FIX */
        @media (max-width: 768px) {

          .main-container {
            flex-direction: column;
          }

          .login-left {
            display: none;
          }

          .login-right {
            max-width: 100%;
            padding: 20px;
          }

          .form-container {
            max-width: 100%;
          }

        }

      `}</style>
    </div>
  );
}
